local LSM = LibStub("LibSharedMedia-3.0")

local font, sound, statusbar = LSM.MediaType.FONT, LSM.MediaType.SOUND, LSM.MediaType.STATUSBAR
local koKR, ruRU, zhCN, zhTW, western = LSM.LOCALE_BIT_koKR, LSM.LOCALE_BIT_ruRU, LSM.LOCALE_BIT_zhCN, LSM.LOCALE_BIT_zhTW, LSM.LOCALE_BIT_western

-- LibSharedMedia applies the locale mask to fonts only. Asia and western sounds share
-- keys (1-10, AoE), so unfiltered the Asia voice registered first wins everywhere and
-- western clients list Chinese names they cannot render.
local clientMask = ({ koKR = koKR, ruRU = ruRU, zhCN = zhCN, zhTW = zhTW })[GetLocale()] or western
local function RegisterSound(key, path, langmask)
    if bit.band(langmask, clientMask) ~= 0 then
        LSM:Register(sound, key, path)
    end
end

